-- ══════════════════════════════════════════════════════════════
--  แก้ชื่อสินค้า 60 ชิ้นที่รับเข้ามาผิดชื่อ ให้เป็น "SgData-ULC"
--  เขียนเมื่อ 3 ก.ย. 2569
--
--  ที่มา: ฟอร์มรับเข้าไม่ล้างช่อง "ชื่อสินค้า" หลังบันทึก และการเติมชื่อ
--  อัตโนมัติจากรหัสจะทำงานเฉพาะตอนช่องชื่อว่าง พอเปลี่ยนรหัสเป็นตัวใหม่
--  ชื่อเก่าที่ค้างอยู่จึงถูกบันทึกติดไปด้วย โดยไม่มีอะไรเตือน
--
--  ทำไมไม่ใช้ปุ่ม "เปลี่ยนชื่อสินค้า" ในเว็บ: ปุ่มนั้นเปลี่ยนตาม "ชื่อ"
--  จะไปโดนของ SgDataPOS-P-W12-15T-15T และ SgDataPOS-CD410 ตัวจริงที่มี
--  อยู่ในคลังด้วย สคริปต์นี้ระบุเป็นราย SN จึงแตะเฉพาะ 60 ชิ้นที่ตั้งใจ
--
--  วิธีใช้: Supabase → SQL Editor → รันทีละขั้น อ่านผลก่อนไปขั้นถัดไป
-- ══════════════════════════════════════════════════════════════

-- ── ขั้นที่ 1: ดูก่อนว่าตอนนี้ 60 SN นี้ชื่ออะไรอยู่บ้าง ──────────
select name as ชื่อปัจจุบัน,
       code as รหัส,
       count(*) as จำนวนชิ้น
from public.inventory
where sn in (
  '2025100101200','2025100101199','2025100101198','2025100101197','2025100101196',
  '2025100101195','2025100101194','2025100101193','2025100101184','2025100101183',
  '2025100101182','2025100101181','2025100101180','2025100100896','2025100100895',
  '2025100100894','2025100100893','2025100100892','2025100100891','2025100100890',
  '2025100100889','2025100100816','2025100100815','2025100100814','2025100100813',
  '2025100100812','2025100100811','2025100100810','2025100100809','2025100100808',
  '2025100100807','2025100100806','2025100100805','2025100100804','2025100100803',
  '2025100100802','2025100100801','2025100100800','2025100100799','2025100100798',
  '2025100100797','2025100100796','2025100100795','2025100100794','2025100100793',
  '2025100100791','2025100100790','2025100100789','2025100100788','2025100100787',
  '2025100100786','2025100100785','2025100100768','2025100100767','2025100100766',
  '2025100100765','2025100100764','2025100100763','2025100100762','2025100100761'
)
group by name, code
order by count(*) desc;

-- ── ขั้นที่ 2: เช็คว่ามี SN ไหนหาไม่เจอในคลังบ้าง (ควรได้ 0 แถว) ──
select s.sn as sn_ที่หาไม่เจอ
from (values
  ('2025100101200'),('2025100101199'),('2025100101198'),('2025100101197'),('2025100101196'),
  ('2025100101195'),('2025100101194'),('2025100101193'),('2025100101184'),('2025100101183'),
